// jaack.js — bundle of components/*.js except theme.js (generated by build.sh). Load with defer.
// Background parallax: the background (never the data) moves at 0.2× scroll, capped at 25 % of the viewport.
// Disabled below 768 px and under prefers-reduced-motion. No inline script needed: include with <script src defer>.
(function(){'use strict';
  var bg=document.querySelector('.jk-bg');if(!bg)return;
  var rm=function(){try{return matchMedia('(prefers-reduced-motion: reduce)').matches}catch(e){return false}};
  var tick=false;function upd(){tick=false;if(rm()||innerWidth<768){bg.style.transform='';return;}bg.style.transform='translate3d(0,'+(-Math.min(scrollY*.2,innerHeight*.25)).toFixed(1)+'px,0)';}
  addEventListener('scroll',function(){if(!tick){tick=true;requestAnimationFrame(upd);}},{passive:true});addEventListener('resize',upd);upd();
})();
// Nav pill: <div class="jk-pill" role="group" aria-label="…"><button aria-pressed="true" data-v="a">A</button>…</div>
// JaackPill.init(el, onChange) wires keyboard (←/→), the sliding indicator and aria-pressed. Auto-inits [data-jk-pill].
(function(root){'use strict';var P={};
  P.init=function(el,on){if(!el||el._jk)return el&&el._jk;var ind=document.createElement('span');ind.className='jk-ind';ind.setAttribute('aria-hidden','true');el.insertBefore(ind,el.firstChild);
    var bs=[].slice.call(el.querySelectorAll('button'));
    function place(){var b=el.querySelector('button[aria-pressed="true"]')||bs[0];if(!b)return;ind.style.width=b.offsetWidth+'px';ind.style.transform='translateX('+b.offsetLeft+'px)';}
    function set(b,fire){bs.forEach(function(x){x.setAttribute('aria-pressed',x===b?'true':'false')});place();if(fire&&on)on(b.dataset.v,b);}
    el.addEventListener('click',function(e){var b=e.target.closest('button');if(b&&el.contains(b))set(b,true);});
    el.addEventListener('keydown',function(e){var i=bs.indexOf(document.activeElement);if(i<0)return;var j=e.key==='ArrowRight'?i+1:e.key==='ArrowLeft'?i-1:-1;if(j<0||j>=bs.length)return;e.preventDefault();bs[j].focus();set(bs[j],true);});
    addEventListener('resize',place);if(document.fonts&&document.fonts.ready)document.fonts.ready.then(place);place();
    return el._jk={set:function(v){var b=bs.filter(function(x){return x.dataset.v===v})[0];if(b)set(b,false);},place:place};};
  root.JaackPill=P;
  document.addEventListener('DOMContentLoaded',function(){[].forEach.call(document.querySelectorAll('[data-jk-pill]'),function(el){P.init(el)});});
})(window);
// Tooltips.
// 1) Elements with data-jk-tip="text" get a glass tooltip on hover and keyboard focus.
// 2) JaackTip.scrub(box, n, html) turns a chart container into a scrubber: pointer x → index 0..n-1 → html(i) (return null to hide).
//    Text is inserted with textContent unless html() returns a DOM-safe string you built yourself — never pass untrusted input.
(function(root){'use strict';var T={};
  function make(host,wrap){var t=document.createElement('div');t.className='jk-tip jk-glass'+(wrap?' wrap':'');t.setAttribute('role','tooltip');host.appendChild(t);return t;}
  function pos(t,host,x,y){var w=t.offsetWidth,h=t.offsetHeight,W=host.clientWidth;var l=Math.max(0,Math.min(W-w,x-w/2));t.style.transform='translate('+l+'px,'+Math.max(0,y-h-10)+'px)';}
  T.scrub=function(box,n,html){box.classList.add('jk-tipwrap');var t=make(box),hr=document.createElement('div');hr.className='jk-hair';box.appendChild(hr);
    function mv(e){var r=box.getBoundingClientRect(),x=e.clientX-r.left,i=Math.max(0,Math.min(n-1,Math.floor(x/r.width*n)));var s=html(i);if(s==null){out();return;}
      t.innerHTML=s;t.classList.add('on');hr.classList.add('on');var cx=(i+.5)/n*r.width;hr.style.transform='translateX('+cx+'px)';pos(t,box,cx,24);}
    function out(){t.classList.remove('on');hr.classList.remove('on');}
    box.addEventListener('pointermove',mv);box.addEventListener('pointerdown',mv);box.addEventListener('pointerleave',out);};
  function attach(el){var host=el.offsetParent||document.body,t=null;
    function show(){if(!t){t=make(document.body,true);t.style.position='fixed';}t.textContent=el.getAttribute('data-jk-tip');var r=el.getBoundingClientRect();t.classList.add('on');
      var w=t.offsetWidth,l=Math.max(8,Math.min(innerWidth-w-8,r.left+r.width/2-w/2));t.style.transform='translate('+l+'px,'+Math.max(8,r.top-t.offsetHeight-8)+'px)';el.setAttribute('aria-describedby',t.id||(t.id='jktip'+Math.random().toString(36).slice(2,8)));}
    function hide(){if(t)t.classList.remove('on');}
    el.addEventListener('mouseenter',show);el.addEventListener('mouseleave',hide);el.addEventListener('focus',show);el.addEventListener('blur',hide);
    addEventListener('keydown',function(e){if(e.key==='Escape')hide();});}
  root.JaackTip=T;
  document.addEventListener('DOMContentLoaded',function(){[].forEach.call(document.querySelectorAll('[data-jk-tip]'),attach);});
})(window);
// Sheet: any element with data-jk-sheet="#id" opens the <dialog id> as a modal glass sheet; Esc, the × button or a click on the backdrop close it.
(function(){'use strict';
  document.addEventListener('click',function(e){var t=e.target.closest('[data-jk-sheet]');if(t){var d=document.querySelector(t.getAttribute('data-jk-sheet'));if(d&&d.showModal){d.showModal();d._from=t;}return;}
    var x=e.target.closest('.jk-sheet .jk-x');if(x){x.closest('dialog').close();return;}
    if(e.target.matches&&e.target.matches('dialog.jk-sheet'))e.target.close();});
  document.addEventListener('close',function(e){var d=e.target;if(d.matches&&d.matches('dialog.jk-sheet')&&d._from)d._from.focus();},true);
})();
// Fade-in groups when they enter the viewport: opacity only (data never moves or scales). Skipped under reduced motion.
(function(){'use strict';
  var els=[].slice.call(document.querySelectorAll('.jk-fx'));var rm=false;try{rm=matchMedia('(prefers-reduced-motion: reduce)').matches}catch(e){}
  if(rm||!window.IntersectionObserver){els.forEach(function(e){e.classList.add('in')});return;}
  var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}})},{threshold:.15});els.forEach(function(e){io.observe(e)});
})();
